# MAGIC ### D3. Save Features to a Feature Table
# MAGIC
# MAGIC Now that we have our features created, let's store them as a feature table within Databricks Feature Store. We have all the ingredients we need to do this within Databricks Unity Catalog:
# MAGIC
# MAGIC 1. Feature table (Spark DataFrame)
# MAGIC 2. Primary key (designated feature)
# MAGIC
# MAGIC First, instantiate the Feature Engineering client.

# COMMAND ----------

from databricks.feature_engineering import FeatureEngineeringClient

# Instantiate the FeatureEngineeringClient
fe = FeatureEngineeringClient()

# COMMAND ----------

# MAGIC %md
# MAGIC Next, run the following cell to create the feature table in Unity Catalog.

# COMMAND ----------

# Set the feature table name for storage in UC
feature_table_name = f'{DA.catalog_name}.{DA.schema_name}.wine_quality_features'

print(f"The name of the feature table: {feature_table_name}\n\n")

# Create the feature table
fe.create_table(
    name = feature_table_name,
    primary_keys = primary_key,
    df = feature_df2,
    description="Wine quality features",
    tags = {"source": "bronze", "format": "delta"}
)

# COMMAND ----------

